                ok = False
        s += 1.0 if ok else 0.0
    return s / max(1, n)


KIND = SPEC["kind"]
score = {"json": check_json, "csv": check_csv, "report": check_report, "seq": check_seq, "files": check_files}[KIND]()
for n in notes[:14]:
    print(n)
print(json.dumps({"score": round(score, 4)}))
sys.exit(0 if score >= 0.9999 else 1)

