    try:
        if kind == "str":
            return norm(got) == norm(want)
        if kind == "int":
            return num(got) == int(want) and float(num(got)).is_integer()
        if kind == "num":
            return abs(num(got) - float(want)) <= tol + 1e-9
        if kind == "bool":
